'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { useSearchParams } from 'next/navigation'
import ABI from './../abi/giftmoji.json'
import toast, { Toaster } from 'react-hot-toast'
import Web3 from 'web3'
import styles from './Page.module.scss'
import Heading from './../components/Heading'
import { initContract, getReaction, getEmoji } from '@/util/communication'


export default function Page() {
  const [emoji, setEmoji] = useState([])
  const {web3, contract} = initContract()
  let [searchParams] = useSearchParams()
  // const auth = useUpProvider()

  const action = async (e, emoji) => {
    const t = toast.loading(`Waiting for transaction's confirmation`)
    const message = prompt(`Please enter a message:`)

    try {
      // window.lukso.request({ method: 'eth_requestAccounts' }).then((accounts) => {
      contract.methods
        .react(`${auth.contextAccounts[0]}`, emoji.emojiId, web3.utils.toHex(message))
        .send({
          from: auth.accounts[0],
          value: emoji.price,
        })
        .then((res) => {
          console.log(res)

          toast.success(`Done`)
          toast.dismiss(t)

          party.confetti(document.body, {
            count: party.variation.range(20, 40),
          })
        })
        .catch((error) => {
          toast.dismiss(t)
        })
      // })
    } catch (error) {
      console.log(error)
      toast.dismiss(t)
    }
  }

  useEffect(() => {
    getEmoji().then(res => {
      setEmoji(res)
    })
  }, [])

  return (
    <div className={`${styles.page} ms-motion-slideDownIn mt-20`} data-width={`large`}>
      <div className={`__container`} data-width={`large`}>
        <div className={`${styles.grid} grid grid--fit w-100`} style={{ '--data-width': `100px` }}>
          {emoji.length === 0 && (
            <div className={`d-flex align-items-center justify-content-between w-100`} style={{ '--data-width': `58px` }}>
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
            </div>
          )}

          {emoji &&
            emoji.map((item, i) => {
              return (
                <div key={i} data-name={item.name} className={`${styles.emoji} d-flex flex-column align-items-center justify-content-between`} title={item.name} onClick={(e) => action(e, item)}>
                  <figure className={`${styles.emoji__icon}`}>
                    <img
                      className={`animate__animated animate__heartBeat`}
                      src={`/emoji/${item.emoji}.svg`}
                      alt={`${process.env.NEXT_PUBLIC_NAME}`}
                      width={32}
                      height={32}
                    />
                  </figure>

                  <b className={`text-center`}>
                    <span>⏣ </span>
                    <span>{web3.utils.fromWei(item.price, `ether`)}</span>
                  </b>
                </div>
              )
            })}
        </div>
      </div>
    </div>
  )
}
